/// <summary>
/// Gets the number sequence for Custom transaction number.
/// </summary>
/// <returns>
/// Number sequence got.
/// </returns>
public static NumberSequenceReference numRefRebateCustomTransId()
{
    
    NumberSeqScope scope = NumberSeqScopeFactory::createDataAreaScope(curext());
    
    return NumberSeqReference::findReference(extendedTypeNum(METRebateTransId), scope);
    
}

/// <summary>
/// Gets the number sequence for Rebate transaction number from new Number sequence.
/// </summary>
/// <returns>
/// Number sequence got.
/// </returns>
public static NumberSequenceReference numRefOrigRebateTransId()
{
    
    NumberSeqScope scope = NumberSeqScopeFactory::createDataAreaScope(curext());
    
    return NumberSeqReference::findReference(extendedTypeNum(METOrigRebateTransId), scope);
    
}
